+    my $quoted = 0;
+    my $seen_space = 0;
+    for (my $index = 0; $index < length($raw); $index++) {
+        my $character = substr($raw, $index, 1);
+
+        if ($state eq 'single') {
+            if ($character eq q{'}) {
+                $state = 'bare';
+                $quoted = 1;
+            }
+            else {
+                $value .= $character;
+            }
+            next;
+        }
+        if ($state eq 'double') {
+            if ($character eq q{"}) {
+                $state = 'bare';
+                $quoted = 1;
+                next;
+            }
+            if ($character eq q{\\}) {
+                ++$index < length($raw)
+                    or die "unterminated escape in double-quoted configuration value\n";
+                my $escaped = substr($raw, $index, 1);
+                $escaped =~ /["\\\$`]/
+                    or die "unsupported escape in double-quoted configuration value\n";
+                $value .= $escaped;
+                next;
+            }
+            $value .= $character;
+            next;
+        }
+
+        if ($seen_space) {
+            if ($character =~ /[ \t]/) {
+                next;
+            }
+            last if $character eq '#';
+            die "unsupported syntax after configuration value\n";
+        }
+        if ($character =~ /[ \t]/) {
+            $seen_space = 1;
+            next;
+        }
+        last if $character eq '#';
+        if ($character eq q{'}) {
+            $state = 'single';
+            next;
+        }
+        if ($character eq q{"}) {
+            $state = 'double';
+            next;
+        }
+        if ($character eq q{\\}) {
+            ++$index < length($raw)
+                or die "unterminated escape in configuration value\n";
+            my $escaped = substr($raw, $index, 1);
+            $escaped =~ /[\\'# "]/ || $escaped =~ /[A-Za-z0-9._@%:+,\/=-]/
