package TimeshiftManaged::Command;

use strict;
use warnings;

use IPC::Open3 qw(open3);
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Symbol qw(gensym);
use Types::Standard qw(ArrayRef Str);

sub status_from_wait {
    my ($status) = @_;

    return 255 if !defined($status) || $status == -1;
    return 128 + ($status & 127) if $status & 127;
    return $status >> 8;
}

sub run {
    my ($self, @argv) = @_;

    die "command is missing\n" if !@argv || !defined($argv[0]) || $argv[0] eq q{};
    system { $argv[0] } @argv;
    return status_from_wait($?);
}

sub capture {
    my ($self, %args) = @_;

    my $argv = $args{argv};
    ref($argv) eq 'ARRAY' && @{$argv}
        or die "capture requires a non-empty argv array\n";
    defined($argv->[0]) && $argv->[0] ne q{}
        or die "capture requires an executable argv[0]\n";

    open my $null, '>', '/dev/null' or die "cannot open /dev/null: $!\n";
    my ($stdin, $stdout);
    my $pid = eval {
        open3($stdin, $stdout, $null, @{$argv});
    };
    die "cannot execute $argv->[0]: $@\n" if !$pid;

    if (defined $args{input}) {
        print {$stdin} $args{input}
            or die "cannot write command input for $argv->[0]: $!\n";
    }
    close $stdin or die "cannot close command input for $argv->[0]: $!\n";

    local $/;
    my $output = <$stdout>;
    close $stdout or die "cannot close command output for $argv->[0]: $!\n";
    waitpid($pid, 0);

    return (status_from_wait($?), defined($output) ? $output : q{});
}

sub find_executable {
    my ($self, $name) = @_;

    defined($name) && $name =~ /\A[A-Za-z0-9][A-Za-z0-9+._-]*\z/
        or die "invalid executable name\n";
    for my $directory (qw(/usr/sbin /usr/bin /sbin /bin)) {
        my $candidate = "$directory/$name";
        return $candidate if -x $candidate && !-d $candidate;
    }
    return undef;
}

1;

package TimeshiftManaged::Config;

use strict;
use warnings;

use Fcntl qw(O_NOFOLLOW O_RDONLY);
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(ArrayRef Int Str);

has allowed_keys => (
    is       => 'ro',
    isa      => ArrayRef,
    required => 1,
);

has maximum_bytes => (
    is      => 'ro',
    isa     => Int,
    default => sub { 65_536 },
);

has path => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub _read_limited_regular_file {
    my ($self) = @_;

    -l $self->path()
        and die "configuration must not be a symbolic link: " . $self->path() . "\n";
    sysopen my $fh, $self->path(), O_RDONLY | O_NOFOLLOW
        or die "cannot read configuration " . $self->path() . ": $!\n";
    my @stat = stat $fh;
    @stat && -f _
        or die "configuration must be a regular file: " . $self->path() . "\n";
    $stat[7] <= $self->maximum_bytes()
        or die "configuration is too large: " . $self->path() . "\n";
    local $/;
    my $content = <$fh>;
    close $fh or die "cannot close configuration " . $self->path() . ": $!\n";
    return defined($content) ? $content : q{};
}

sub parse_shell_value {
    my ($class, $raw) = @_;

    defined($raw) or die "configuration value is undefined\n";
    $raw =~ /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/
        and die "configuration value contains a control character\n";
    $raw =~ s/\A[ \t]+//;
    $raw =~ s/[ \t]+\z//;
    return q{} if $raw eq q{};

    my $value = q{};
    my $state = 'bare';
    my $quoted = 0;
    my $seen_space = 0;
    for (my $index = 0; $index < length($raw); $index++) {
        my $character = substr($raw, $index, 1);

        if ($state eq 'single') {
            if ($character eq q{'}) {
                $state = 'bare';
                $quoted = 1;
            }
            else {
                $value .= $character;
            }
            next;
        }
        if ($state eq 'double') {
            if ($character eq q{"}) {
                $state = 'bare';
                $quoted = 1;
                next;
            }
            if ($character eq q{\\}) {
                ++$index < length($raw)
                    or die "unterminated escape in double-quoted configuration value\n";
                my $escaped = substr($raw, $index, 1);
                $escaped =~ /["\\\$`]/
                    or die "unsupported escape in double-quoted configuration value\n";
                $value .= $escaped;
                next;
            }
            $value .= $character;
            next;
        }

        if ($seen_space) {
            if ($character =~ /[ \t]/) {
                next;
            }
            last if $character eq '#';
            die "unsupported syntax after configuration value\n";
        }
        if ($character =~ /[ \t]/) {
            $seen_space = 1;
            next;
        }
        last if $character eq '#';
        if ($character eq q{'}) {
            $state = 'single';
            next;
        }
        if ($character eq q{"}) {
            $state = 'double';
            next;
        }
        if ($character eq q{\\}) {
            ++$index < length($raw)
                or die "unterminated escape in configuration value\n";
            my $escaped = substr($raw, $index, 1);
            $escaped =~ /[\\'# "]/ || $escaped =~ /[A-Za-z0-9._@%:+,\/=-]/
                or die "unsupported escape in configuration value\n";
            $value .= $escaped;
            next;
        }
        $character =~ /[A-Za-z0-9._@%:+,\/=\-\[\]\{\}\?]/
            or die "unsupported character in unquoted configuration value\n";
        $value .= $character;
    }
    $state eq 'bare'
        or die "unterminated quoted configuration value\n";
    return $value;
}

sub load {
    my ($self) = @_;

    my %allowed = map { $_ => 1 } @{ $self->allowed_keys() };
    my %values = map { $_ => q{} } @{ $self->allowed_keys() };
    my $content = $self->_read_limited_regular_file();

    my $current = q{};
    for my $line (split /\n/, $content, -1) {
        next if $current eq q{} && $line =~ /\A[ \t]*(?:#|\z)/;
        $current = $current eq q{} ? $line : "$current\n$line";
        my ($raw_value) = $current =~ /\A[A-Za-z_][A-Za-z0-9_]*=(.*)\z/s;
        defined($raw_value)
            or die "invalid configuration assignment in " . $self->path() . "\n";
        my $complete = eval { __PACKAGE__->parse_shell_value($raw_value); 1 };
        if (!$complete) {
            next if $@ =~ /unterminated quoted configuration value/;
            die "invalid configuration value in " . $self->path() . ": $@";
        }
        my ($key, $value) = $current =~ /\A([A-Za-z_][A-Za-z0-9_]*)=(.*)\z/s;
        $allowed{$key}
            or die "unsupported configuration key in " . $self->path() . ": $key\n";
        $values{$key} = __PACKAGE__->parse_shell_value($value);
        $current = q{};
    }
    $current eq q{}
        or die "unterminated quoted configuration assignment in " . $self->path() . "\n";
    return \%values;
}

1;

package TimeshiftManaged::Logger;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Sys::Syslog qw(:standard :macros);
use Types::Standard qw(Str);

has tag => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub log {
    my ($self, $level, $message) = @_;

    my %priority = (
        debug   => LOG_DEBUG,
        info    => LOG_INFO,
        warning => LOG_WARNING,
        error   => LOG_ERR,
    );
    $level = exists $priority{$level} ? $level : 'error';
    $message = q{} if !defined $message;
    $message = "$message";
    $message =~ s/[\r\n]+/ /g;
    $message =~ s/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/?/g;
    $message = substr($message, 0, 2048);

    print STDERR "$level: $message\n" if $level ne 'debug';
    return if !eval {
        openlog($self->tag(), 'pid,nowait', LOG_DAEMON);
        syslog($priority{$level}, '%s', $message);
        closelog();
        1;
    };
    return;
}

sub debug {
    my ($self, $message) = @_;
    return $self->log('debug', $message);
}

sub info {
    my ($self, $message) = @_;
    return $self->log('info', $message);
}

sub warning {
    my ($self, $message) = @_;
    return $self->log('warning', $message);
}

sub error {
    my ($self, $message) = @_;
    return $self->log('error', $message);
}

1;

#!/usr/bin/perl
use strict;
use warnings;

use FindBin qw($Bin);
use lib "$Bin/../libexec/timeshift-managed";

use TimeshiftManaged::CLI;

exit TimeshiftManaged::CLI->new(
    program => 'timeshift-managed-snapshot',
)->run(@ARGV);

package TimeshiftManaged::EventQueue;

use strict;
use warnings;

use Fcntl qw(O_CREAT O_EXCL O_NOFOLLOW O_WRONLY);
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use POSIX qw(strftime);
use Time::HiRes qw(time);
use Types::Standard qw(Int Str);

use TimeshiftManaged::Logger;

has event_root => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

has owner_gid => (
    is       => 'ro',
    isa      => Int,
    required => 1,
);

has owner_uid => (
    is       => 'ro',
    isa      => Int,
    required => 1,
);

has logger => (
    is       => 'ro',
    required => 1,
);

has sequence => (
    is      => 'rw',
    isa     => Int,
    default => sub { 0 },
);

sub event_dir {
    my ($self) = @_;
    return $self->event_root() . '/timeshift';
}

sub _validate_absolute_path {
    my ($self, $label, $value) = @_;

    defined($value) && $value =~ m{\A/}
        or die "$label must be an absolute path\n";
    $value !~ m{(?:^|/)\.\.(?:/|$)}
        or die "$label contains a parent-directory component\n";
    $value !~ m{//}
        or die "$label contains an empty path component\n";
    $value =~ m{\A/[A-Za-z0-9._/@%:+,-]*\z}
        or die "$label contains unsupported path syntax\n";
    return $value;
}

sub _ensure_directory {
    my ($self, $directory) = @_;

    $self->_validate_absolute_path('Timeshift notification path', $directory);
    my $current = q{};
    for my $part (grep { $_ ne q{} } split m{/+}, $directory) {
        $current .= "/$part";
        if (-l $current) {
            die "Timeshift notification path must not be a symlink: $current\n";
        }
        if (-e $current) {
            -d $current
                or die "Timeshift notification path is not a directory: $current\n";
        }
        else {
            mkdir $current, 0755
                or die "cannot create Timeshift notification directory $current: $!\n";
        }
        $self->_set_owner_and_mode($current, 0755);
    }
    return;
}

sub _set_owner_and_mode {
    my ($self, $path, $mode) = @_;

    my $current_uid = $>;
    my ($current_gid) = split /\s+/, $);
    if ($current_uid != $self->owner_uid() || $current_gid != $self->owner_gid()) {
        $current_uid == 0
            or die "Timeshift notification ownership requires root privileges\n";
        chown $self->owner_uid(), $self->owner_gid(), $path
            or die "cannot set Timeshift notification owner for $path: $!\n";
    }
    chmod $mode, $path
        or die "cannot set Timeshift notification mode for $path: $!\n";
    return;
}

sub _prune_expired_events {
    my ($self) = @_;
    my $directory = $self->event_dir();
    my $cutoff = time() - (45 * 24 * 60 * 60);

    opendir my $dh, $directory
        or die "cannot read Timeshift notification directory $directory: $!\n";
    while (my $name = readdir $dh) {
        next if $name !~ /\A[0-9]{10}-[0-9]{10}-[0-9]{4}\.event\z/;
        my $path = "$directory/$name";
        next if -l $path;
        my @stat = lstat $path;
        next if !@stat || !-f _;
        unlink $path
            or die "cannot remove expired Timeshift event $path: $!\n"
            if $stat[9] < $cutoff;
    }
    closedir $dh or die "cannot close Timeshift notification directory $directory: $!\n";
    return;
}

sub emit {
    my ($self, %args) = @_;

    my $status = $args{status};
    my $kind = $args{kind};
    my $detail = $args{detail};
    $status =~ /\A(?:started|completed|failed)\z/
        or die "unsupported Timeshift notification status\n";
    $kind =~ /\A(?:daily|weekly|monthly)\z/
        or die "unsupported Timeshift notification kind\n";
    if ($status eq 'failed') {
        defined($detail) && $detail =~ /\A[0-9]{1,3}\z/ && $detail <= 255
            or die "Timeshift failure notification requires an exit status\n";
    }
    else {
        (!defined($detail) || $detail eq '-')
            or die "Timeshift non-failure notification requires '-' detail\n";
        $detail = '-';
    }

    $self->_ensure_directory($self->event_root());
    $self->_ensure_directory($self->event_dir());
    $self->_prune_expired_events();

    my $epoch = int(time());
    my $sequence = $self->sequence() + 1;
    $self->sequence($sequence);
    my $name = sprintf '%010d-%010d-%04d.event', $epoch, $$, $sequence;
    my $temporary = $self->event_dir() . "/.$name.tmp";
    my $event = $self->event_dir() . "/$name";

    sysopen my $fh, $temporary, O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW, 0644
        or die "cannot create Timeshift event $temporary: $!\n";
    print {$fh} "$status|$kind|$detail\n"
        or die "cannot write Timeshift event $temporary: $!\n";
    close $fh or die "cannot close Timeshift event $temporary: $!\n";
    $self->_set_owner_and_mode($temporary, 0644);
    rename $temporary, $event
        or die "cannot publish Timeshift event $event: $!\n";
    return;
}

1;

#!/usr/bin/perl
use strict;
use warnings;

use FindBin qw($Bin);
use lib "$Bin/../libexec/timeshift-managed";

use TimeshiftManaged::CLI;

exit TimeshiftManaged::CLI->new(
    program => 'grub-btrfs-refresh',
)->run(@ARGV);

package TimeshiftManaged::CLI;

use strict;
use warnings;

use Moo;
use MooX::Options
  protect_argv => 0,
  flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Bool Str);

use TimeshiftManaged::GrubRefresh;
use TimeshiftManaged::Logger;
use TimeshiftManaged::Snapshot;

option help => (
    is      => 'ro',
    isa     => Bool,
    default => sub { 0 },
    doc     => 'print usage',
);

has program => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub _usage {
    my ($self) = @_;

    if ($self->program() eq 'timeshift-managed-snapshot') {
        print STDERR "usage: timeshift-managed-snapshot {daily|weekly|monthly}\n";
    }
    else {
        print STDERR "usage: grub-btrfs-refresh [--wait]\n";
    }
    return;
}

sub run {
    my ($self, @argv) = @_;

    local @ARGV = @argv;
    my $options = eval { __PACKAGE__->new_with_options(program => $self->program()) };
    if (!$options) {
        my $error = $@ || 'invalid command line';
        $error =~ s/\s+\z//;
        print STDERR "fatal: $error\n";
        return 1;
    }
    if ($options->help()) {
        $options->_usage();
        return 0;
    }

    if ($options->program() eq 'timeshift-managed-snapshot') {
        @ARGV == 1 or do {
            $options->_usage();
            return 1;
        };
        my $snapshot = eval { TimeshiftManaged::Snapshot->from_environment($ARGV[0]) };
        if (!$snapshot) {
            my $error = $@ || 'invalid Timeshift snapshot configuration';
            $error =~ s/\s+\z//;
            TimeshiftManaged::Logger->new(tag => 'timeshift-managed-snapshot')->error($error);
            return 1;
        }
        return $snapshot->run();
    }

    return TimeshiftManaged::GrubRefresh->new()->run(@ARGV);
}

1;

package TimeshiftManaged::Snapshot;

use strict;
use warnings;

use Fcntl qw(:flock O_CREAT O_NOFOLLOW O_WRONLY);
use File::Basename qw(dirname);
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Time::HiRes qw(sleep time);
use Types::Standard qw(Int Str);

use TimeshiftManaged::Command;
use TimeshiftManaged::EventQueue;
use TimeshiftManaged::Logger;

has binary => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

has event_owner_gid => (
    is       => 'ro',
    isa      => Int,
    required => 1,
);

has event_owner_uid => (
    is       => 'ro',
    isa      => Int,
    required => 1,
);

has event_root => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

has kind => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

has lock_file => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

has lock_timeout_seconds => (
    is       => 'ro',
    isa      => Int,
    required => 1,
);

has logger => (
    is       => 'ro',
    required => 1,
);

has command => (
    is      => 'ro',
    default => sub { TimeshiftManaged::Command->new() },
);

sub from_environment {
    my ($class, $kind) = @_;

    return $class->new(
        binary               => $ENV{TIMESHIFT_BINARY} // '/usr/bin/timeshift',
        event_owner_gid      => _integer_from_environment('TIMESHIFT_EVENT_OWNER_GID', 0, 0, 2_147_483_647),
        event_owner_uid      => _integer_from_environment('TIMESHIFT_EVENT_OWNER_UID', 0, 0, 2_147_483_647),
        event_root           => $ENV{TIMESHIFT_EVENT_ROOT} // '/var/lib/labwc-notifications',
        kind                 => $kind,
        lock_file            => $ENV{TIMESHIFT_LOCK_FILE} // '/run/lock/timeshift-managed-snapshot.lock',
        lock_timeout_seconds => _integer_from_environment('TIMESHIFT_LOCK_TIMEOUT_SECONDS', 1800, 1, 21600),
        logger               => TimeshiftManaged::Logger->new(tag => 'timeshift-managed-snapshot'),
    );
}

sub _integer_from_environment {
    my ($name, $default, $minimum, $maximum) = @_;

    my $value = exists $ENV{$name} ? $ENV{$name} : $default;
    defined($value) && $value =~ /\A[0-9]+\z/
        or die "$name must be numeric\n";
    $value >= $minimum && $value <= $maximum
        or die "$name must be between $minimum and $maximum\n";
    return int($value);
}

sub _validate_absolute_path {
    my ($self, $label, $value) = @_;

    defined($value) && $value =~ m{\A/}
        or die "$label must be an absolute path\n";
    $value !~ m{(?:^|/)\.\.(?:/|$)}
        or die "$label contains a parent-directory component\n";
    $value !~ m{//}
        or die "$label contains an empty path component\n";
    $value =~ m{\A/[A-Za-z0-9._/@%:+,-]*\z}
        or die "$label contains unsupported path syntax\n";
    return;
}

sub _ensure_directory {
    my ($self, $directory) = @_;

    $self->_validate_absolute_path('Timeshift lock directory', $directory);
    my $current = q{};
    for my $part (grep { $_ ne q{} } split m{/+}, $directory) {
        $current .= "/$part";
        -l $current
            and die "Timeshift lock directory must not be a symlink: $current\n";
        if (-e $current) {
            -d $current
                or die "Timeshift lock directory is not a directory: $current\n";
        }
        else {
            mkdir $current, 0755
                or die "cannot create Timeshift lock directory $current: $!\n";
        }
    }
    return;
}

sub _validate {
    my ($self) = @_;

    $self->kind() =~ /\A(?:daily|weekly|monthly)\z/
        or die "unsupported managed Timeshift snapshot kind: " . $self->kind() . "\n";
    $self->_validate_absolute_path('Timeshift binary', $self->binary());
    $self->_validate_absolute_path('Timeshift event root', $self->event_root());
    $self->_validate_absolute_path('Timeshift lock file', $self->lock_file());
    -x $self->binary()
        or die "Timeshift binary is not executable: " . $self->binary() . "\n";
    return;
}

sub _queue {
    my ($self) = @_;

    return TimeshiftManaged::EventQueue->new(
        event_root => $self->event_root(),
        logger     => $self->logger(),
        owner_gid  => $self->event_owner_gid(),
        owner_uid  => $self->event_owner_uid(),
    );
}

sub _emit_or_warn {
    my ($self, $queue, %args) = @_;

    return if eval { $queue->emit(%args); 1 };
    my $error = $@ || 'unknown notification error';
    $error =~ s/\s+\z//;
    $self->logger()->warning("failed to queue Timeshift notification: $error");
    return;
}

sub _acquire_lock {
    my ($self) = @_;

    my $directory = dirname($self->lock_file());
    $self->_ensure_directory($directory);
    -l $self->lock_file()
        and die "Timeshift lock file must not be a symlink: " . $self->lock_file() . "\n";
    sysopen my $fh, $self->lock_file(), O_WRONLY | O_CREAT | O_NOFOLLOW, 0600
        or die "cannot open Timeshift snapshot lock: " . $self->lock_file() . ": $!\n";

    my $deadline = time() + $self->lock_timeout_seconds();
    while (!flock($fh, LOCK_EX | LOCK_NB)) {
        return undef if time() >= $deadline;
        sleep 0.2;
    }
    return $fh;
}

sub _command_arguments {
    my ($self) = @_;
    my %schedule = (
        daily   => ['D', 'Scheduled eight-times-daily snapshot'],
        weekly  => ['W', 'Scheduled twice-weekly snapshot'],
        monthly => ['M', 'Scheduled monthly snapshot'],
    );
    my ($tag, $comment) = @{ $schedule{ $self->kind() } };
    return (
        $self->binary(),
        '--create',
        '--scripted',
        '--yes',
        '--quiet',
        '--btrfs',
        '--tags',
        $tag,
        '--comments',
        $comment,
    );
}

sub run {
    my ($self) = @_;

    my $result = eval {
        $self->_validate();
        my $queue = $self->_queue();
        my $lock = $self->_acquire_lock();
        if (!$lock) {
            $self->logger()->warning('timed out waiting for the managed Timeshift snapshot lock');
            $self->_emit_or_warn($queue, status => 'failed', kind => $self->kind(), detail => 75);
            return 75;
        }

        $self->_emit_or_warn($queue, status => 'started', kind => $self->kind(), detail => '-');
        $self->logger()->info('starting managed Timeshift ' . $self->kind() . ' snapshot');
        local $ENV{PATH} = '/usr/local/libexec/timeshift-managed:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin';
        my $status = $self->command()->run($self->_command_arguments());
        if ($status == 0) {
            $self->_emit_or_warn($queue, status => 'completed', kind => $self->kind(), detail => '-');
            $self->logger()->info('completed managed Timeshift ' . $self->kind() . ' snapshot');
        }
        else {
            $self->_emit_or_warn($queue, status => 'failed', kind => $self->kind(), detail => $status);
            $self->logger()->error("managed Timeshift " . $self->kind() . " snapshot failed with status $status");
        }
        return $status;
    };

    if (!$result && $@) {
        my $error = $@;
        $error =~ s/\s+\z//;
        $self->logger()->error($error);
        return 1;
    }
    return $result;
}

1;

package TimeshiftManaged::GrubRefresh;

use strict;
use warnings;

use Fcntl qw(:flock O_CREAT O_NOFOLLOW O_WRONLY);
use File::Basename qw(basename dirname);
use File::Temp qw(tempfile);
use JSON::PP qw(decode_json);
use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Time::HiRes qw(sleep time);
use Types::Standard qw(Int Str);

use TimeshiftManaged::Command;
use TimeshiftManaged::Config;
use TimeshiftManaged::Logger;

has grub_btrfs_config => (
    is      => 'ro',
    isa     => Str,
    default => sub { '/etc/default/grub-btrfs/config' },
);

has logger => (
    is      => 'ro',
    default => sub { TimeshiftManaged::Logger->new(tag => 'grub-btrfs-refresh') },
);

has lock_file => (
    is      => 'ro',
    isa     => Str,
    default => sub { '/run/lock/grub-btrfs-refresh.lock' },
);

has output_file => (
    is      => 'ro',
    isa     => Str,
    default => sub { '/boot/grub/grub-btrfs.cfg' },
);

has profile_config => (
    is      => 'ro',
    isa     => Str,
    default => sub { '/etc/default/grub-profiles.conf' },
);

has command => (
    is      => 'ro',
    default => sub { TimeshiftManaged::Command->new() },
);

sub _require_absolute_path {
    my ($self, $label, $value) = @_;

    defined($value) && $value =~ m{\A/}
        or die "$label must be an absolute path\n";
    $value !~ m{(?:^|/)\.\.(?:/|$)} && $value !~ m{//}
        or die "$label contains unsafe path syntax\n";
    return;
}

sub _ensure_directory {
    my ($self, $directory, $mode) = @_;

    $self->_require_absolute_path('runtime directory', $directory);
    my $current = q{};
    for my $part (grep { $_ ne q{} } split m{/+}, $directory) {
        $current .= "/$part";
        -l $current
            and die "runtime directory must not be a symbolic link: $current\n";
        if (-e $current) {
            -d $current
                or die "runtime directory is not a directory: $current\n";
        }
        else {
            mkdir $current, $mode
                or die "cannot create runtime directory $current: $!\n";
        }
        chmod $mode, $current
            or die "cannot set runtime directory mode for $current: $!\n";
    }
    return;
}

sub _acquire_lock {
    my ($self) = @_;

    my $lock_dir = dirname($self->lock_file());
    $self->_ensure_directory($lock_dir, 0755);
    -l $self->lock_file()
        and die "refresh lock must not be a symbolic link: " . $self->lock_file() . "\n";
    sysopen my $fh, $self->lock_file(), O_WRONLY | O_CREAT | O_NOFOLLOW, 0600
        or die "cannot open refresh lock " . $self->lock_file() . ": $!\n";
    if (!flock($fh, LOCK_EX | LOCK_NB)) {
        $self->logger()->info('another grub-btrfs-refresh run is active; skipping this event');
        return undef;
    }
    return $fh;
}

sub _runtime_snapshot_active {
    my ($self) = @_;

    for my $directory (glob('/run/timeshift/*/backup/timeshift-btrfs/snapshots')) {
        return 1 if -d $directory;
    }
    return 0;
}

sub _wait_for_timeshift_exit {
    my ($self) = @_;

    my $deadline = time() + 300;
    while ($self->_runtime_snapshot_active()) {
        time() < $deadline
            or die "Timeshift runtime mounts did not disappear within 300s\n";
        sleep 1;
    }
    return;
}

sub _mount_path_is_active {
    my ($self, $mount_path) = @_;

    open my $fh, '<', '/proc/mounts'
        or die "cannot read /proc/mounts: $!\n";
    while (my $line = <$fh>) {
        my @fields = split /\s+/, $line;
        if (@fields >= 2 && $fields[1] eq $mount_path) {
            close $fh;
            return 1;
        }
    }
    close $fh or die "cannot close /proc/mounts: $!\n";
    return 0;
}

sub _program {
    my ($self, $name) = @_;

    my $program = $self->command()->find_executable($name);
    defined($program)
        or die "required executable is unavailable: $name\n";
    return $program;
}

sub _cleanup_mount_path {
    my ($self, $mount_path) = @_;

    return if !defined($mount_path) || $mount_path eq q{};
    if ($self->_mount_path_is_active($mount_path)) {
        my $status = $self->command()->run($self->_program('umount'), $mount_path);
        if ($status != 0) {
            $self->command()->run($self->_program('umount'), '-l', $mount_path);
        }
    }
    rmdir $mount_path if -d $mount_path && !-l $mount_path;
    return;
}

sub _cleanup_stale_mount_roots {
    my ($self) = @_;

    for my $stale_root (glob('/run/grub-btrfs-refresh.*')) {
        next if !-d $stale_root || -l $stale_root;
        $self->_cleanup_mount_path($stale_root);
    }
    return;
}

sub _load_configurations {
    my ($self) = @_;

    return undef if !-r $self->profile_config() || !-r $self->grub_btrfs_config();
    my $profile = TimeshiftManaged::Config->new(
        allowed_keys => [
            qw(
              dev_part_boot dev_part_root bootprofile_default bootprofile_performance
              bootprofile_hardened grub_root_flags grub_initramfs_flags grub_nvme_flags
              grub_systemd_mask_flags grub_cgroup_flags grub_security_core_flags
              grub_blacklist_flags grub_vfio_flags grub_memory_core_flags
              grub_hardening_flags grub_aspm_flags grub_profile_default_flags
              grub_profile_performance_flags grub_profile_hardened_flags
              grub_gfxpayload_linux
            )
        ],
        path => $self->profile_config(),
    )->load();
    my $grub_btrfs = TimeshiftManaged::Config->new(
        allowed_keys => [
            qw(GRUB_BTRFS_SNAPSHOT_DIR GRUB_BTRFS_ROOT_SUBVOLUME GRUB_BTRFS_LIMIT GRUB_BTRFS_STATE_DIR)
        ],
        path => $self->grub_btrfs_config(),
    )->load();
    return ($profile, $grub_btrfs);
}

sub _validate_relative_subvolume_path {
    my ($self, $label, $value) = @_;

    defined($value) && $value ne q{}
        or die "$label must not be empty\n";
    $value !~ m{\A/} && $value !~ m{//}
        or die "$label must be relative and contain no empty path components\n";
    $value !~ m{(?:^|/)\.\.(?:/|$)}
        or die "$label contains a parent-directory component\n";
    $value =~ /\A[A-Za-z0-9@._/+:-]+\z/
        or die "$label contains unsupported characters\n";
    return;
}

sub _bootable_kernel_images {
    my ($self) = @_;

    my @images = grep {
        my $version = $_;
        $version =~ s{\A/boot/vmlinuz-}{};
        -e "/boot/initrd.img-$version";
    } glob('/boot/vmlinuz-*');
    return () if !@images;
    my ($status, $output) = $self->command()->capture(
        argv  => [ $self->_program('sort'), '-Vr' ],
        input => join(q{}, map { "$_\n" } @images),
    );
    $status == 0 or die "cannot sort bootable kernel images\n";
    return grep { $_ ne q{} } split /\n/, $output;
}

sub _uuid_for_device {
    my ($self, $device) = @_;

    defined($device) && $device =~ m{\A/dev/[A-Za-z0-9._/+:-]+\z}
        or die "invalid block-device path\n";
    my ($status, $output) = $self->command()->capture(
        argv => [ $self->_program('blkid'), '-s', 'UUID', '-o', 'value', $device ],
    );
    return q{} if $status != 0;
    $output =~ s/[\r\n]+\z//;
    $output =~ /\A[A-Za-z0-9-]+\z/
        or return q{};
    return $output;
}

sub _snapshot_writable {
    my ($self, $snapshot_subvolume) = @_;

    my ($status, $output) = $self->command()->capture(
        argv => [ $self->_program('btrfs'), 'property', 'get', '-ts', $snapshot_subvolume, 'ro' ],
    );
    return 0 if $status != 0;
    $output =~ s/\s+\z//;
    return $output eq 'ro=false' ? 1 : 0;
}

sub _snapshot_metadata {
    my ($self, $snapshot_dir) = @_;

    my $info_file = "$snapshot_dir/info.json";
    return (q{}, q{}) if !-r $info_file || -l $info_file;
    my @stat = stat $info_file;
    return (q{}, q{}) if !@stat || !-f _ || $stat[7] > 1_048_576;
    open my $fh, '<', $info_file or return (q{}, q{});
    local $/;
    my $raw = <$fh>;
    close $fh;
    my $metadata = eval { decode_json($raw // q{}) };
    return (q{}, q{}) if !$metadata || ref($metadata) ne 'HASH';
    my $tag = ref($metadata->{tags}) ? q{} : ($metadata->{tags} // q{});
    my $comment = ref($metadata->{comments}) ? q{} : ($metadata->{comments} // q{});
    my %labels = (
        B => 'boot',
        D => 'daily',
        H => 'hourly',
        M => 'monthly',
        O => 'ondemand',
        W => 'weekly',
    );
    $tag = $labels{$tag} // $tag;
    $comment =~ s/[\r\n\x00-\x1f\x7f]/ /g;
    $comment = substr($comment, 0, 160);
    return ($tag, $comment);
}

sub _grub_single_quote {
    my ($self, $value) = @_;

    $value //= q{};
    $value =~ s/'/'\\''/g;
    return $value;
}

sub _grub_id_fragment {
    my ($self, $value) = @_;

    $value //= q{};
    $value =~ s/[^A-Za-z0-9_]/_/g;
    return $value;
}

sub _format_snapshot_timestamp {
    my ($self, $value) = @_;

    $value =~ s/_/ /;
    $value =~ s/(\d{2})-(\d{2})-(\d{2})\z/$1:$2:$3/;
    return $value;
}

sub _snapshot_root_flags {
    my ($self, $grub_root_flags, $snapshot_dir_rel, $snapshot_name, $root_subvolume) = @_;

    my $snapshot_subvolume = $snapshot_dir_rel;
    $snapshot_subvolume =~ s{/+\z}{};
    $root_subvolume =~ s{\A/+}{};
    $snapshot_subvolume .= "/$snapshot_name/$root_subvolume";
    if ($grub_root_flags =~ /rootflags=subvol=@,/) {
        $grub_root_flags =~ s/rootflags=subvol=@,/rootflags=subvol=$snapshot_subvolume,/;
        return $grub_root_flags;
    }
    if ($grub_root_flags =~ /rootflags=subvol=@/) {
        $grub_root_flags =~ s/rootflags=subvol=@/rootflags=subvol=$snapshot_subvolume/;
        return $grub_root_flags;
    }
    return "$grub_root_flags rootflags=subvol=$snapshot_subvolume";
}

sub _fallback_menu {
    return <<'GRUB';
# Managed by installer automation.
set timeout=-1

menuentry 'No BTRFS snapshots available' {
    echo 'No BTRFS snapshots are available.'
}

menuentry 'Return to main menu' --id 'installer-snapshot-return' --class os {
    configfile $prefix/grub.cfg
}
GRUB
}

sub _render_snapshot_menu {
    my ($self, %args) = @_;

    my $snapshot_root = $args{snapshot_root};
    my $snapshot_dir_rel = $args{snapshot_dir_rel};
    my $root_subvolume = $args{root_subvolume};
    my $kernel_images = $args{kernel_images};
    my $profile = $args{profile};
    my $root_arg = $args{root_arg};
    my $boot_search = $args{boot_search};
    my $base_cmdline = $args{base_cmdline};
    my $limit = $args{limit};

    my @profiles = (
        [ $profile->{bootprofile_default}, 'Balanced',    $profile->{grub_profile_default_flags} ],
        [ $profile->{bootprofile_performance}, 'Performance', $profile->{grub_profile_performance_flags} ],
        [ $profile->{bootprofile_hardened}, 'Hardened',   $profile->{grub_profile_hardened_flags} ],
    );
    my @lines = ("# Managed by installer automation.\n", "set timeout=-1\n\n");
    my $rendered = 0;
    my $count = 0;

    opendir my $dh, $snapshot_root
        or die "cannot read Timeshift snapshot root $snapshot_root: $!\n";
    my @snapshots = sort { $b cmp $a } grep {
        $_ ne q{.} && $_ ne q{..} && -d "$snapshot_root/$_" && !-l "$snapshot_root/$_";
    } readdir $dh;
    closedir $dh or die "cannot close Timeshift snapshot root $snapshot_root: $!\n";

    SNAPSHOT:
    for my $snapshot_name (@snapshots) {
        if ($snapshot_name !~ /\A\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\z/) {
            $self->logger()->warning("ignoring malformed Timeshift snapshot directory: $snapshot_name");
            next;
        }
        my $subvolume = "$snapshot_root/$snapshot_name/$root_subvolume";
        next SNAPSHOT if !-d $subvolume || -l $subvolume;
        if (!$self->_snapshot_writable($subvolume)) {
            $self->logger()->warning("ignoring read-only or unreadable Timeshift snapshot: $snapshot_name");
            next;
        }

        my ($tag, $comment) = $self->_snapshot_metadata("$snapshot_root/$snapshot_name");
        my $title = $self->_format_snapshot_timestamp($snapshot_name);
        $title .= " [$tag]" if $tag ne q{};
        $title .= " $comment" if $comment ne q{};
        my $entry_id = 'installer_snapshot_' . $self->_grub_id_fragment($snapshot_name);
        my $root_flags = $self->_snapshot_root_flags(
            $profile->{grub_root_flags},
            $snapshot_dir_rel,
            $snapshot_name,
            $root_subvolume,
        );
        my @snapshot_lines;
        my $has_entries = 0;
        for my $profile_spec (@profiles) {
            my ($profile_name, $profile_label, $profile_flags) = @{$profile_spec};
            next if !defined($profile_name) || $profile_name eq q{};
            my @profile_lines;
            for my $kernel_image (@{$kernel_images}) {
                my $kernel_version = $kernel_image;
                $kernel_version =~ s{\A/boot/vmlinuz-}{};
                next if !-d "$subvolume/lib/modules/$kernel_version";
                my $kernel_id = $self->_grub_id_fragment($kernel_version);
                my $profile_id = $self->_grub_id_fragment($profile_name);
                push @profile_lines,
                    "    menuentry '" . $self->_grub_single_quote("[$profile_label] $kernel_version")
                    . "' --id '${entry_id}_${profile_id}_${kernel_id}' --class debian --class gnu-linux --class gnu --class os {\n",
                    "        if [ -s \$prefix/grubenv ]; then\n",
                    "            set installer_linux_last_profile='$profile_name'\n",
                    "            set installer_linux_last_kernel='$kernel_version'\n",
                    "            save_env installer_linux_last_profile\n",
                    "            save_env installer_linux_last_kernel\n",
                    "        fi\n",
                    "        insmod gzio\n",
                    "        insmod zstd\n",
                    "        insmod part_gpt\n",
                    "        insmod ext2\n",
                    "        $boot_search\n";
                if (($profile->{grub_gfxpayload_linux} // q{}) ne q{}) {
                    push @profile_lines,
                        "        set gfxpayload='" . $self->_grub_single_quote($profile->{grub_gfxpayload_linux}) . "'\n";
                }
                push @profile_lines,
                    "        linux   /vmlinuz-$kernel_version $root_arg ro $root_flags $base_cmdline systemd.setenv=BOOTPROFILE=$profile_name $profile_flags\n",
                    "        initrd  /initrd.img-$kernel_version\n",
                    "    }\n";
            }
            next if !@profile_lines;
            push @snapshot_lines,
                "submenu '" . $self->_grub_single_quote($profile_label)
                . "' --id '${entry_id}_" . $self->_grub_id_fragment($profile_name)
                . "' --class debian --class gnu-linux --class gnu --class os {\n",
                @profile_lines,
                "}\n";
            $has_entries = 1;
        }
        next if !$has_entries;
        push @lines,
            "submenu '" . $self->_grub_single_quote($title)
            . "' --id '$entry_id' --class snapshots --class btrfs --class os {\n",
            @snapshot_lines,
            "}\n\n";
        $rendered = 1;
        ++$count;
        last if $limit > 0 && $count >= $limit;
    }

    if (!$rendered) {
        return $self->_fallback_menu();
    }
    push @lines, <<'GRUB';
menuentry 'Return to main menu' --id 'installer-snapshot-return' --class os {
    configfile $prefix/grub.cfg
}
GRUB
    return join q{}, @lines;
}

sub _install_menu {
    my ($self, $menu) = @_;

    my $output_dir = dirname($self->output_file());
    $self->_ensure_directory($output_dir, 0755);
    my ($fh, $temporary) = tempfile(basename($self->output_file()) . '.XXXXXX', DIR => $output_dir, UNLINK => 0);
    print {$fh} $menu
        or die "cannot write generated grub-btrfs menu: $!\n";
    close $fh or die "cannot close generated grub-btrfs menu: $!\n";
    chmod 0644, $temporary
        or die "cannot set generated grub-btrfs menu mode: $!\n";
    my $checker = $self->command()->find_executable('grub-script-check');
    if ($checker) {
        my $status = $self->command()->run($checker, $temporary);
        $status == 0
            or die "generated grub-btrfs.cfg failed grub-script-check\n";
    }
    rename $temporary, $self->output_file()
        or die "cannot publish generated grub-btrfs menu: $!\n";
    return;
}

sub run {
    my ($self, @argv) = @_;

    my $result = eval {
        @argv <= 1 && (!@argv || $argv[0] eq '--wait')
            or die "unsupported grub-btrfs-refresh mode\n";
        $self->_require_absolute_path('output file', $self->output_file());
        $self->_require_absolute_path('refresh lock file', $self->lock_file());
        my $lock = $self->_acquire_lock();
        return 0 if !$lock;
        $self->_wait_for_timeshift_exit() if @argv && $argv[0] eq '--wait';
        my ($profile, $grub_btrfs) = $self->_load_configurations();
        return 0 if !$profile;
        return 0 if ($profile->{dev_part_root} // q{}) eq q{} || ($profile->{dev_part_boot} // q{}) eq q{};

        my $snapshot_dir_rel = $grub_btrfs->{GRUB_BTRFS_SNAPSHOT_DIR} // 'timeshift-btrfs/snapshots';
        my $root_subvolume = $grub_btrfs->{GRUB_BTRFS_ROOT_SUBVOLUME} // '@';
        my $snapshot_limit = $grub_btrfs->{GRUB_BTRFS_LIMIT} // 50;
        my $state_dir = $grub_btrfs->{GRUB_BTRFS_STATE_DIR} // '/run/grub-btrfs-refresh';
        $self->_validate_relative_subvolume_path('GRUB_BTRFS_SNAPSHOT_DIR', $snapshot_dir_rel);
        $self->_validate_relative_subvolume_path('GRUB_BTRFS_ROOT_SUBVOLUME', $root_subvolume);
        $state_dir =~ m{\A/run/[A-Za-z0-9._/@%:+,-]+\z}
            or die "GRUB_BTRFS_STATE_DIR must be below /run and contain safe path syntax\n";
        $snapshot_limit =~ /\A[0-9]+\z/ && $snapshot_limit <= 200
            or die "GRUB_BTRFS_LIMIT must be numeric and not exceed 200\n";
        $snapshot_limit = int($snapshot_limit);

        my @kernel_images = $self->_bootable_kernel_images();
        if (!@kernel_images) {
            $self->_install_menu($self->_fallback_menu());
            return 0;
        }

        my $root_uuid = $self->_uuid_for_device($profile->{dev_part_root});
        $root_uuid ne q{}
            or die "unable to determine UUID for $profile->{dev_part_root}\n";
        my $boot_uuid = $self->_uuid_for_device($profile->{dev_part_boot});
        my $default_version = $kernel_images[0];
        $default_version =~ s{\A/boot/vmlinuz-}{};
        my $boot_search = $boot_uuid ne q{}
            ? "search --no-floppy --fs-uuid --set=root $boot_uuid"
            : "search --no-floppy --file --set=root /vmlinuz-$default_version";
        my $base_cmdline = join q{ },
            map { $profile->{$_} // q{} } qw(
              grub_initramfs_flags grub_nvme_flags grub_systemd_mask_flags grub_cgroup_flags
              grub_security_core_flags grub_blacklist_flags grub_vfio_flags grub_memory_core_flags
              grub_hardening_flags grub_aspm_flags
            );

        $self->_cleanup_stale_mount_roots();
        $self->_ensure_directory($state_dir, 0700);
        my $mount_root = "$state_dir/root";
        $self->_cleanup_mount_path($mount_root);
        $self->_ensure_directory($mount_root, 0700);
        my $mounted = 0;
        my $cleanup = sub {
            $self->_cleanup_mount_path($mount_root) if $mounted || -d $mount_root;
            rmdir $state_dir if -d $state_dir && !-l $state_dir;
        };
        my $render_result = eval {
            my $status = $self->command()->run(
                $self->_program('mount'),
                '-o',
                'ro,subvolid=5',
                "/dev/disk/by-uuid/$root_uuid",
                $mount_root,
            );
            $status == 0
                or die "cannot mount Btrfs top-level subvolume for GRUB snapshot refresh\n";
            $mounted = 1;
            my $snapshot_root = "$mount_root/$snapshot_dir_rel";
            if (!-d $snapshot_root || -l $snapshot_root) {
                $self->_install_menu($self->_fallback_menu());
                return 0;
            }
            my $menu = $self->_render_snapshot_menu(
                base_cmdline     => $base_cmdline,
                boot_search      => $boot_search,
                kernel_images    => \@kernel_images,
                limit            => $snapshot_limit,
                profile          => $profile,
                root_arg         => "root=UUID=$root_uuid",
                root_subvolume   => $root_subvolume,
                snapshot_dir_rel => $snapshot_dir_rel,
                snapshot_root    => $snapshot_root,
            );
            $self->_install_menu($menu);
            return 0;
        };
        my $error = $@;
        $cleanup->();
        die $error if !$render_result && $error;
        return $render_result;
    };

    if (!$result && $@) {
        my $error = $@;
        $error =~ s/\s+\z//;
        $self->logger()->error($error);
        return 1;
    }
    $self->logger()->info('refreshed GRUB Btrfs snapshot menu') if $result == 0;
    return $result;
}

1;

