+            or die "AppArmor draft exceeds " . $self->maximum_draft_bytes() . " bytes: $path\n";
+        my $status = $self->command()->run(
+            $parser, '--config-file', '/etc/apparmor/parser.conf', '-q', '-Q', '-K', '-T', $path,
