+        $activation_status == 0
+            or die "AppArmor draft activation failed with status $activation_status; the previous profile will be restored\n";
+        $published = 0;
+        $renamed = 0;
+        print "Activated AppArmor draft: $origin/$canonical -> $target\n";
+        if ($target_existed) {
