    19	sub _status {
    20	    my ($status) = @_;
    21	
    22	    return 255 if !defined($status) || $status == -1;
    23	    return 128 + ($status & 127) if $status & 127;
    24	    return $status >> 8;
    25	}
    26	
    27	sub executable {
    28	    my ($self, $name) = @_;
    29	
    30	    defined($name) && $name =~ /\A[A-Za-z0-9][A-Za-z0-9+._-]*\z/
    31	        or die "invalid executable name\n";
    32	    for my $directory (split /:/, $self->path()) {
    33	        next if $directory !~ m{\A/};
    34	        my $candidate = "$directory/$name";
    35	        return $candidate if -x $candidate && !-d $candidate;
    36	    }
    37	    return undef;
    38	}
    39	
    40	sub require_executable {
    41	    my ($self, $name) = @_;
    42	
    43	    my $program = $self->executable($name);
    44	    defined($program)
    45	        or die "required security command is not installed: $name\n";
    46	    return $program;
    47	}
    48	
    49	sub run {
    50	    my ($self, @argv) = @_;
    51	
    52	    @argv && defined($argv[0]) && $argv[0] ne q{}
    53	        or die "cannot run an empty command\n";
    54	    system { $argv[0] } @argv;
    55	    return _status($?);
    56	}
    57	
    58	sub exec {
    59	    my ($self, @argv) = @_;
    60	
    61	    @argv && defined($argv[0]) && $argv[0] ne q{}
    62	        or die "cannot execute an empty command\n";
    63	    exec { $argv[0] } @argv;
    64	    die "cannot execute $argv[0]: $!\n";
    65	}
    66	
    67	sub capture {
    68	    my ($self, %args) = @_;
    69	
    70	    my $argv = $args{argv};
    71	    ref($argv) eq 'ARRAY' && @{$argv}
    72	        or die "capture requires a non-empty argv array\n";
    73	    open my $null, '>', '/dev/null' or die "cannot open /dev/null: $!\n";
    74	    my ($stdin, $stdout);
    75	    my $pid = eval { open3($stdin, $stdout, $null, @{$argv}) };
    76	    die "cannot execute $argv->[0]: $@\n" if !$pid;
    77	    if (defined $args{input}) {
    78	        print {$stdin} $args{input}
    79	            or die "cannot write command input for $argv->[0]: $!\n";
    80	    }
    81	    close $stdin or die "cannot close command input for $argv->[0]: $!\n";
    82	    local $/;
    83	    my $output = <$stdout>;
    84	    close $stdout or die "cannot close command output for $argv->[0]: $!\n";
    85	    waitpid($pid, 0);
    86	    return (_status($?), defined($output) ? $output : q{});
    87	}
