   259	sub _profile_labels {
   260	    my ($self, $source) = @_;
   261	
   262	    $self->_prepare_backup_dir();
   263	    my $parser = $self->_program('apparmor_parser');
   264	    my ($status, $output) = $self->command()->capture(
   265	        argv => [
