   294	sub _resolve_installed_profile_name {
   295	    my ($self, $source, $requested_name) = @_;
   296	
   297	    $self->_validate_draft_name($requested_name);
   298	    my $candidate_labels = $self->_profile_labels($source);
   299	    opendir my $dh, $self->profile_dir()
   300	        or die "cannot read AppArmor profile directory: " . $self->profile_dir() . ": $!\n";
   301	    my @matches;
   302	    my $count = 0;
   303	    while (my $name = readdir $dh) {
   304	        next if $name eq q{.} || $name eq q{..};
   305	        my $path = $self->profile_dir() . "/$name";
   306	        next if !-f $path || -l $path;
   307	        ++$count;
   308	        $count <= $self->maximum_installed_profile_files()
   309	            or die "more than " . $self->maximum_installed_profile_files() . " installed AppArmor profile files were found\n";
   310	        $self->_validate_draft_name($name);
   311	        my $installed_labels = $self->_profile_labels($path);
   312	        push @matches, $name if $self->_same_labels($candidate_labels, $installed_labels);
   313	    }
   314	    closedir $dh or die "cannot close AppArmor profile directory: $!\n";
   315	
   316	    if (!@matches) {
   317	        my $target = $self->profile_dir() . "/$requested_name";
   318	        (!-e $target && !-l $target)
   319	            or die "AppArmor draft profile labels do not match the installed target: $requested_name\n";
   320	        return $requested_name;
   321	    }
   322	    @matches == 1
   323	        or die "AppArmor draft profile labels match multiple installed targets: $requested_name\n";
