   327	sub _merge_draft {
   328	    my ($self, $generated, $target, $label) = @_;
   329	
   330	    $self->_parser_validate($generated) == 0
   331	        or die "$label generated invalid AppArmor policy: " . basename($generated) . "\n";
   332	    if (!-e $target) {
   333	        copy($generated, $target)
   334	            or die "cannot write AppArmor draft $target: $!\n";
   335	        chmod 0644, $target or die "cannot set AppArmor draft mode: $!\n";
   336	        print "Generated non-active $label draft: $target\n";
   337	        return;
   338	    }
   339	
   340	    $self->_validate_root_owned_file('existing AppArmor profile draft', $target);
   341	    my @generated = split /\n/, $self->_read_small_file($generated, $self->maximum_draft_bytes(), 'generated AppArmor draft'), -1;
   342	    my @existing = split /\n/, $self->_read_small_file($target, $self->maximum_draft_bytes(), 'existing AppArmor draft'), -1;
   343	    grep { $_ =~ /^\s*}\s*$/ } @generated
   344	        or die "generated AppArmor draft does not terminate the profile block\n";
   345	    my %generated_lines = map { (my $line = $_) =~ s/\s+\z//; $line => 1 } @generated;
   346	    my @extras;
   347	    for my $line (@existing) {
   348	        (my $trimmed = $line) =~ s/\s+\z//;
   349	        my $stripped = $trimmed;
   350	        $stripped =~ s/\A\s+//;
   351	        next if $stripped eq q{} || $stripped eq '}' || $stripped =~ /\A#/;
   352	        next if $stripped =~ /\Aabi\s/ || $stripped =~ /\A#include <tunables\/global>/;
   353	        next if $stripped =~ /\Aprofile\s/ || $stripped =~ /\Ainclude if exists <local\//;
   354	        push @extras, $trimmed if !$generated_lines{$trimmed};
   355	    }
   356	    my @merged = @generated;
   357	    if (@extras) {
   358	        my $index;
   359	        for my $candidate (0 .. $#merged) {
   360	            if ($merged[$candidate] =~ /^\s*include if exists <local\//) {
   361	                $index = $candidate;
   362	                last;
   363	            }
   364	        }
   365	        if (!defined $index) {
   366	            for (my $candidate = $#merged; $candidate >= 0; --$candidate) {
   367	                if ($merged[$candidate] =~ /^\s*}\s*$/) {
   368	                    $index = $candidate;
   369	                    last;
   370	                }
   371	            }
   372	        }
   373	        defined($index)
   374	            or die "generated AppArmor draft has no merge anchor\n";
   375	        splice @merged, $index, 0, @extras;
   376	    }
   377	    my ($fh, $temporary) = tempfile(basename($target) . '.merge.XXXXXX', DIR => dirname($target), UNLINK => 0);
   378	    print {$fh} join("\n", @merged), "\n"
   379	        or die "cannot write merged AppArmor draft: $!\n";
   380	    close $fh or die "cannot close merged AppArmor draft: $!\n";
   381	    if ($self->_parser_validate($temporary) == 0) {
   382	        copy($temporary, $target)
   383	            or die "cannot publish merged AppArmor draft: $!\n";
   384	        chmod 0644, $target or die "cannot set AppArmor draft mode: $!\n";
   385	        print "Merged non-active $label draft into existing profile: $target\n";
   386	    }
   387	    else {
   388	        copy($generated, $target)
   389	            or die "cannot replace AppArmor draft: $!\n";
   390	        chmod 0644, $target or die "cannot set AppArmor draft mode: $!\n";
   391	        print "Replaced existing $label draft with the newly generated profile: $target\n";
   392	    }
   393	    unlink $temporary;
   394	    return;
   395	}
