   397	sub _publish_generated_drafts {
   398	    my ($self, $work_dir, $label) = @_;
   399	
   400	    my @files = sort grep { -f $_ && !-l $_ } glob("$work_dir/*");
   401	    @files && @files <= $self->maximum_draft_files()
