    39	    my ($self, $label, $path) = @_;
    40	    if (!-e $path) {
    41	        make_path($path, { mode => 0700 }) or _fatal("cannot create $label");
    42	    }
    43	    -d $path && !-l $path && (lstat $path)[4] == $<
    44	        or _fatal("$label must be a user-owned real directory");
    45	    chmod 0700, $path or _fatal("cannot secure $label: $!");
