    72	sub validate_wav {
    73	    my ($self, $state) = @_;
    74	    my $paths = $self->paths();
    75	    my $expected = "$paths->{audio}/$state->{stem}.wav";
    76	    $state->{wav} eq $expected or _fatal('runtime state recording escaped the managed audio directory');
    77	    return $expected;
    78	}
    79	
    80	sub _atomic_write {
    81	    my ($self, $directory, $name, $content) = @_;
    82	    $name =~ /\A[0-9A-Za-z._-]+\z/ or _fatal('unsafe artifact name');
    83	    my ($fh, $temporary) = tempfile(".$name.XXXXXX", DIR => $directory, UNLINK => 0);
    84	    binmode $fh, ':raw';
    85	    print {$fh} $content or _fatal("cannot write temporary artifact: $!");
    86	    close $fh or _fatal("cannot close temporary artifact: $!");
    87	    chmod 0600, $temporary or _fatal("cannot secure temporary artifact: $!");
    88	    rename $temporary, "$directory/$name" or _fatal("cannot publish artifact: $!");
    89	}
    90	
    91	sub store_transcript {
    92	    my ($self, $stem, $text) = @_;
    93	    my $paths = $self->paths();
    94	    $self->_atomic_write($paths->{transcribed}, "$stem.json", encode_json({ text => $text }) . "\n");
    95	}
    96	
    97	sub append_task {
    98	    my ($self, $stem, $text) = @_;
    99	    return if !length $text;
   100	    my $sleek = $self->sleek();
   101	    sysopen my $lock, "$sleek->{directory}/.whisper.txt.lock", O_CREAT | O_NOFOLLOW | O_RDWR, 0600
   102	        or _fatal("cannot open Sleek task lock: $!");
   103	    flock($lock, LOCK_EX) or _fatal("cannot lock Sleek task file: $!");
   104	    open my $fh, '>>:encoding(UTF-8)', $sleek->{task_file}
   105	        or _fatal("cannot append Sleek task: $!");
   106	    print {$fh} substr($stem, 0, 10), " $text +whisper \@voice source:$stem\n"
   107	        or _fatal("cannot write Sleek task: $!");
   108	    close $fh or _fatal("cannot close Sleek task: $!");
   109	}
   110	
   111	sub prune {
   112	    my ($self, $directory, $extension) = @_;
   113	    opendir my $dh, $directory or _fatal("cannot read artifact directory: $!");
   114	    my @files = sort { $b cmp $a } grep {
   115	        /\A[0-9]{4}(?:-[0-9]{2}){5}\.\Q$extension\E\z/ &&
   116	        -f "$directory/$_" && !-l "$directory/$_"
   117	    } readdir $dh;
   118	    closedir $dh or _fatal("cannot close artifact directory: $!");
   119	    for my $name (@files[$self->max_artifacts() .. $#files]) {
   120	        unlink "$directory/$name" or _fatal("cannot prune managed artifact: $name");
   121	    }
   122	}
   123	
   124	sub read_json {
   125	    my ($self, $path, $limit, $label) = @_;
   126	    -f $path && !-l $path && -s $path <= $limit
   127	        or _fatal("$label is missing, unsafe, or too large");
   128	    open my $fh, '<:raw', $path or _fatal("cannot read $label: $!");
   129	    local $/;
   130	    my $raw = <$fh> // q{};
   131	    close $fh or _fatal("cannot close $label: $!");
   132	    my $data = eval { decode_json($raw) };
   133	    $@ || ref($data) eq 'HASH' or _fatal("$label is not valid JSON");
   134	    return $data;
   135	}
   136	
   137	1;

