     1	package WhisperMode::Config;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Moo;
     7	use MooX::StrictConstructor;
     8	use MooX::TypeTiny;
     9	use POSIX qw(sysconf);
    10	use Types::Standard qw(HashRef Str);
    11	
    12	has path => (
    13	    is      => 'ro',
    14	    isa     => Str,
    15	    default => sub { $ENV{WHISPER_CONFIG_FILE} // '/etc/whisper/whisper.conf' },
    16	);
    17	
    18	has values => (
    19	    is      => 'lazy',
    20	    isa     => HashRef,
    21	    builder => '_build_values',
    22	);
    23	
    24	sub _fatal {
    25	    my ($message) = @_;
    26	    die "whisper-record-toggle: $message\n";
    27	}
    28	
    29	sub _safe_absolute_file {
    30	    my ($label, $path, $executable) = @_;
    31	    defined($path) && $path =~ m{\A/} && $path !~ m{\0|(?:\A|/)\.\.(?:/|\z)|//}
    32	        or _fatal("$label is invalid");
    33	    -f $path && !-l $path or _fatal("$label is unavailable: $path");
    34	    $executable ? -x $path : -r $path
    35	        or _fatal("$label is not accessible: $path");
    36	    return $path;
    37	}
    38	
    39	sub _build_values {
    40	    my ($self) = @_;
    41	    my $path = $self->path();
    42	    _safe_absolute_file('Whisper configuration', $path, 0);
    43	    my @stat = lstat $path;
    44	    ($stat[2] & 0022) == 0
    45	        or _fatal('Whisper configuration must not be writable by group or other users');
    46	    if ($path eq '/etc/whisper/whisper.conf') {
    47	        $stat[4] == 0 or _fatal('default Whisper configuration must be owned by root');
    48	    } else {
    49	        $stat[4] == $< or _fatal('override Whisper configuration must be owned by the active user');
    50	    }
    51	    -s $path <= 16 * 1024 or _fatal('Whisper configuration is too large');
    52	
    53	    open my $fh, '<:raw', $path or _fatal("cannot read Whisper configuration: $!");
    54	    my %values;
    55	    while (my $line = <$fh>) {
    56	        $line =~ s/\r?\n\z//;
    57	        next if $line eq q{} || $line =~ /\A#/;
    58	        $line =~ /\A([A-Z_]+)=([^\r\n]*)\z/
    59	            or _fatal('Whisper configuration contains an invalid line');
    60	        exists $values{$1} and _fatal("Whisper configuration contains duplicate $1");
    61	        $values{$1} = $2;
    62	    }
    63	    close $fh or _fatal("cannot close Whisper configuration: $!");
    64	
    65	    for my $key (qw(WHISPER_CLI WHISPER_SERVER WHISPER_MODEL WHISPER_RUNTIME_THREADS WHISPER_PERSISTENT_MEM)) {
    66	        defined $values{$key} && length $values{$key}
    67	            or _fatal("Whisper configuration is missing $key");
    68	    }
    69	    _safe_absolute_file('WHISPER_CLI', $values{WHISPER_CLI}, 1);
    70	    _safe_absolute_file('WHISPER_SERVER', $values{WHISPER_SERVER}, 1);
    71	    _safe_absolute_file('WHISPER_MODEL', $values{WHISPER_MODEL}, 0);
    72	    $values{WHISPER_RUNTIME_THREADS} =~ /\A(?:auto|[1-9][0-9]*)\z/
    73	        or _fatal('WHISPER_RUNTIME_THREADS must be auto or a positive integer');
    74	    $values{WHISPER_PERSISTENT_MEM} =~ /\A[01]\z/
    75	        or _fatal('WHISPER_PERSISTENT_MEM must be 0 or 1');
    76	    return \%values;
    77	}
    78	
    79	sub value {
    80	    my ($self, $key) = @_;
    81	    return $self->values()->{$key};
    82	}
    83	
    84	sub persistent_memory_enabled {
    85	    my ($self) = @_;
    86	    return $self->value('WHISPER_PERSISTENT_MEM') eq '1';
    87	}
    88	
    89	sub thread_count {
    90	    my ($self) = @_;
    91	    my $configured = $self->value('WHISPER_RUNTIME_THREADS');
    92	    return $configured if $configured ne 'auto';
    93	    my $count = eval { sysconf(POSIX::_SC_NPROCESSORS_ONLN()) };
    94	    return $count if defined $count && $count =~ /\A[1-9][0-9]*\z/;
    95	    return 1;
    96	}
    97	
    98	1;

