     1	package WhisperMode::Logger;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use Exporter qw(import);
     7	use Sys::Syslog qw(:standard :macros);
     8	
     9	our @EXPORT_OK = qw(log_msg);
    10	
    11	my %PRIORITY = (
    12	    debug   => LOG_DEBUG,
    13	    info    => LOG_INFO,
    14	    warning => LOG_WARNING,
    15	    error   => LOG_ERR,
    16	);
    17	
    18	sub log_msg {
    19	    my ($level, $message) = @_;
    20	    $level = exists $PRIORITY{$level} ? $level : 'error';
    21	    $message = q{} if !defined $message;
    22	    $message =~ s/[\r\n]+/ /g;
    23	    $message =~ s/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/?/g;
    24	    $message = substr($message, 0, 2048);
    25	
    26	    return if !eval {
    27	        openlog('whisper-record-toggle', 'pid,nowait', LOG_USER);
    28	        syslog($PRIORITY{$level}, '%s', $message);
    29	        closelog();
    30	        1;
    31	    };
    32	}
