     1	package WhisperMode::Recorder;
     2	
     3	use strict;
     4	use warnings;
     5	
     6	use POSIX qw(strftime);
     7	use Time::HiRes qw(sleep);
     8	use Moo;
     9	use MooX::StrictConstructor;
    10	use MooX::TypeTiny;
    11	use WhisperMode::Logger qw(log_msg);
    12	
    13	has artifacts => ( is => 'ro', required => 1 );
    14	has audio     => ( is => 'ro', required => 1 );
    15	has state     => ( is => 'ro', required => 1 );
    16	has systemd   => ( is => 'ro', required => 1 );
    17	
    18	sub _fatal {
    19	    my ($message) = @_;
    20	    die "whisper-record-toggle: $message\n";
    21	}
    22	
    23	sub _stem {
    24	    my ($self, $directory) = @_;
    25	    for (1 .. 3) {
    26	        my $stem = strftime('%Y-%m-%d-%H-%M-%S', localtime);
    27	        return $stem if !-e "$directory/$stem.wav";
    28	        sleep 1;
    29	    }
    30	    _fatal('could not create a collision-free recording name');
    31	}
    32	
    33	sub start {
    34	    my ($self) = @_;
    35	    my $paths = $self->artifacts()->paths();
    36	    my $existing = $self->state()->read();
    37	    if ($self->systemd()->is_active($self->systemd()->record_service())) {
    38	        $existing or _fatal('recording service is active without managed runtime state');
    39	        $self->artifacts()->validate_wav($existing);
    40	        $self->audio()->set_default_source_muted(0);
    41	        return;
    42	    }
    43	    if ($existing) {
    44	        my $wav = $self->artifacts()->validate_wav($existing);
    45	        -s $wav > 44 and _fatal('a completed recording is pending transcription');
    46	        $self->state()->clear();
    47	    }
    48	    my $stem = $self->_stem($paths->{audio});
    49	    $self->state()->write({ stem => $stem, wav => "$paths->{audio}/$stem.wav" });
    50	    $self->audio()->set_default_source_muted(0);
    51	    eval { $self->systemd()->start_recording(); 1 } or do {
    52	        my $error = $@ || 'unknown recorder failure';
    53	        $self->state()->clear();
    54	        eval { $self->audio()->set_default_source_muted(1) };
    55	        die $error;
    56	    };
    57	    log_msg('info', "started Whisper recording $stem");
    58	}
    59	
    60	sub stop {
    61	    my ($self) = @_;
    62	    my $recording = $self->state()->read();
    63	    $self->systemd()->stop_recording();
    64	    $self->audio()->set_default_source_muted(1);
    65	    return undef if !$recording;
    66	    my $wav = $self->artifacts()->validate_wav($recording);
    67	    if (!-f $wav || -l $wav || -s $wav <= 44) {
    68	        $self->state()->clear();
    69	        return undef;
    70	    }
    71	    log_msg('info', "stopped Whisper recording $recording->{stem}");
    72	    return $recording;
    73	}
    74	
    75	sub record_worker {
    76	    my ($self) = @_;
    77	    my $recording = $self->state()->read()
    78	        or _fatal('recorder service started without managed runtime state');
    79	    my $guard = $self->state()->lock(1, 1)
    80	        or _fatal('a Whisper recording is already active');
    81	    my $wav = $self->artifacts()->validate_wav($recording);
    82	    $self->audio()->record($wav);
    83	}
