     8	use MooX::TypeTiny;
     9	use WhisperMode::Artifacts;
    10	use WhisperMode::Audio;
    11	use WhisperMode::Config;
    12	use WhisperMode::Logger qw(log_msg);
    13	use WhisperMode::Memory;
    14	use WhisperMode::Recorder;
    15	use WhisperMode::State;
    16	use WhisperMode::Systemd;
    17	use WhisperMode::Transcriber;
    18	
    19	has config => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Config->new() } );
    20	has state => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::State->new() } );
    21	has artifacts => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Artifacts->new() } );
    22	has audio => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Audio->new() } );
    23	has systemd => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Systemd->new() } );
    24	
    25	sub _recorder {
    26	    my ($self) = @_;
    27	    return WhisperMode::Recorder->new(
    28	        artifacts => $self->artifacts(), audio => $self->audio(),
    29	        state => $self->state(), systemd => $self->systemd(),
    30	    );
    31	}
    32	
    33	sub _memory {
    34	    my ($self) = @_;
    35	    return WhisperMode::Memory->new(config => $self->config(), systemd => $self->systemd());
    36	}
    37	
    38	sub run {
    39	    my ($self, $action) = @_;
    40	    if ($action eq 'server-enabled') {
    41	        $self->_memory()->enabled() or die "whisper-record-toggle: WHISPER_PERSISTENT_MEM is disabled\n";
    42	        return 0;
    43	    }
    44	    if ($action eq 'server') {
    45	        $self->_memory()->run_server();
    46	        return 0;
    47	    }
    48	    if ($action eq 'record-worker') {
    49	        my $lock = $self->state()->lock(0, 0);
    50	        $self->_recorder()->record_worker();
    51	        return 0;
    52	    }
    53	    if ($action eq 'transcribe') {
    54	        my $lock = $self->state()->lock(0, 0);
    55	        WhisperMode::Transcriber->new(
    56	            artifacts => $self->artifacts(), config => $self->config(),
    57	            memory => $self->_memory(), state => $self->state(),
    58	        )->transcribe_pending();
    59	        return 0;
    60	    }
    61	
    62	    my $lock = $self->state()->lock(0, 0);
    63	    my $recorder = $self->_recorder();
    64	    my $pending = $self->state()->read();
    65	    my $transcribe = 0;
    66	    if ($action eq 'toggle') {
    67	        if ($self->systemd()->is_active($self->systemd()->record_service()) || $pending) {
    68	            $transcribe = defined $recorder->stop();
    69	        } else {
    70	            $recorder->start();
    71	        }
    72	    } elsif ($action eq 'start') {
    73	        $recorder->start();
    74	    } elsif ($action eq 'stop') {
    75	        $transcribe = defined $recorder->stop();
    76	    } else {
    77	        die "whisper-record-toggle: unsupported action: $action\n";
    78	    }
    79	    undef $lock;
    80	    $self->systemd()->start_transcription() if $transcribe;
    81	    return 0;
    82	}
    83	
    84	1;

