    13	
    14	has runtime_directory => (
    15	    is      => 'ro',
    16	    isa     => Str,
    17	    lazy    => 1,
    18	    builder => '_build_runtime_directory',
    19	);
    20	
    21	sub _fatal {
    22	    my ($message) = @_;
    23	    die "whisper-record-toggle: $message\n";
