    25	
    26	sub _build_runtime_directory {
    27	    $< != 0 or _fatal('must not run as root');
    28	    my $path = $ENV{XDG_RUNTIME_DIR};
    29	    defined($path) && $path =~ m{\A/run/user/[1-9][0-9]*\z}
    30	        or _fatal('XDG_RUNTIME_DIR is invalid');
    31	    -d $path && !-l $path or _fatal('XDG_RUNTIME_DIR must be a real directory');
    32	    my @stat = lstat $path;
    33	    $stat[4] == $< && ($stat[2] & 0077) == 0
    34	        or _fatal('XDG_RUNTIME_DIR ownership or mode is unsafe');
    35	    return $path;
    36	}
