    38	sub _path {
    39	    my ($self, $name) = @_;
    40	    $name =~ /\A(?:whisper-record-toggle\.(?:lock|recording|state)|\.whisper-[0-9-]+-[0-9]+\.json)\z/
    41	        or _fatal('unsafe managed runtime file name');
