    11	
    12	my %LOG_LEVEL_VALUE = (
    13	    debug   => 10,
    14	    info    => 20,
    15	    warning => 30,
    16	    error   => 40,
    17	    none    => 99,
    18	);
    19	
    20	has active_level => (
    21	    is      => 'rw',
    22	    isa     => Str,
    23	    default => sub { 'error' },
    24	);
    25	
    26	sub canonical_log_level {
    27	    my ($class, $level) = @_;
    28	
    29	    $level = lc($level // 'info');
    30	    return 'warning' if $level eq 'warn';
    31	    return $level if exists $LOG_LEVEL_VALUE{$level};
    32	    return 'info';
    33	}
    34	
    35	sub validate_active_level {
    36	    my ($self) = @_;
    37	
    38	    my $raw = lc($self->active_level() // q{});
    39	    $raw =~ /\A(?:debug|info|warn|warning|error|none)\z/
    40	        or die "SYSTEMD_LOG_LEVEL must be debug, info, warning, error, or none\n";
    41	    $self->active_level(__PACKAGE__->canonical_log_level($raw));
    42	    return;
    43	}
    44	
    45	sub enabled {
    46	    my ($self, $level) = @_;
    47	
    48	    my $requested = __PACKAGE__->canonical_log_level($level);
    49	    return 1 if $requested eq 'error';
    50	    my $active = __PACKAGE__->canonical_log_level($self->active_level());
    51	    return 0 if $active eq 'none';
    52	    return $LOG_LEVEL_VALUE{$requested} >= $LOG_LEVEL_VALUE{$active};
    53	}
    54	
    55	sub log {
    56	    my ($self, $level, $message) = @_;
    57	
    58	    $level = __PACKAGE__->canonical_log_level($level);
    59	    return if !$self->enabled($level);
    60	    $message = q{} if !defined $message;
    61	    $message = "$message";
    62	    $message =~ s/[\r\n]+/ /g;
    63	    $message =~ s/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/?/g;
    64	    $message = substr($message, 0, 2048);
    65	    my $line = "$level: $message";
    66	    print STDERR "$line\n";
    67	
    68	    my %priority = (
    69	        debug   => LOG_DEBUG,
    70	        info    => LOG_INFO,
    71	        warning => LOG_WARNING,
    72	        error   => LOG_ERR,
    73	    );
    74	    return if !eval {
    75	        openlog('managed-network', 'pid,nowait', LOG_USER);
    76	        syslog($priority{$level}, '%s', $line);
    77	        closelog();
    78	        1;
    79	    };
    80	    return;
    81	}
