    51	    defined $value && $value =~ /\A(?:debug|info|warning|warn|error|fatal|none)\z/i
    52	        or fatal("runtime.log_level must be debug, info, warning, error, or none");
    53	    $value = lc($value);
    54	    return 'warning' if $value eq 'warn';
    55	    return 'error' if $value eq 'fatal';
    56	    return $value;
    57	}
    58	
    59	sub _validate_name_token {
    60	    my ($label, $value) = @_;
    61	    defined $value && $value =~ /\A[A-Za-z0-9_.:+-]+\z/
    62	        or fatal("$label contains unsafe characters: '" . (defined $value ? $value : 'unset') . "'");
    63	    return $value;
    64	}
    65	
    66	sub _validate_key_size_bits {
    67	    my ($label, $value) = @_;
    68	    my $bits = ensure_positive_uint($label, $value);
    69	    $bits % 8 == 0 or fatal("$label must be a multiple of 8 bits");
    70	    return $bits;
    71	}
    72	
    73	sub _validate_algorithm_params {
    74	    my ($label, $value) = @_;
    75	    return '' if !defined $value || $value eq '';
    76	    length($value) <= 512 or fatal("$label is too large");
    77	    $value !~ /[\x00-\x1f\x7f]/ or fatal("$label contains control characters");
    78	    for my $token (split /\s+/, $value) {
    79	        $token =~ /\A[A-Za-z0-9_.:+-]+=[A-Za-z0-9_.:+-]+\z/
    80	            or fatal("$label contains unsupported parameter token: $token");
    81	    }
    82	    return $value;
    83	}
    84	
    85	sub _validate_recompression_type {
    86	    my ($label, $value) = @_;
    87	    defined $value && $value =~ /\A(?:idle|huge_idle|huge)\z/
    88	        or fatal("$label must be idle, huge_idle, or huge, got '" . (defined $value ? $value : 'unset') . "'");
    89	    return $value;
    90	}
    91	
    92	sub _ensure_range {
    93	    my ($label, $value, $minimum, $maximum) = @_;
    94	    ($value >= $minimum && $value <= $maximum)
    95	        or fatal("$label must be between $minimum and $maximum, got $value");
    96	    return $value;
    97	}
