    99	sub _validate_known_config_keys {
   100	    my ($raw) = @_;
   101	    my $defaults = default_config();
   102	    for my $section (sort keys %{$raw}) {
   103	        exists $defaults->{$section} or fatal("unknown zram config section [$section]");
   104	        ref($raw->{$section}) eq 'HASH' or fatal("invalid zram config section [$section]");
   105	        for my $key (sort keys %{$raw->{$section}}) {
   106	            exists $defaults->{$section}{$key} or fatal("unknown zram config key [$section].$key");
   107	        }
   108	    }
   109	}
