    16	sub ensure_uint {
    17	    my ($label, $value) = @_;
    18	    defined $value && $value =~ /\A[0-9]+\z/
    19	        or fatal("$label must be an integer, got '" . (defined $value ? $value : 'unset') . "'");
    20	    return 0 + $value;
    21	}
    22	
    23	sub ensure_positive_uint {
    24	    my ($label, $value) = @_;
    25	    my $int = ensure_uint($label, $value);
    26	    $int > 0 or fatal("$label must be greater than zero");
    27	    return $int;
    28	}
    29	
    30	sub ensure_sint {
    31	    my ($label, $value) = @_;
    32	    defined $value && $value =~ /\A-?[0-9]+\z/
    33	        or fatal("$label must be an integer, got '" . (defined $value ? $value : 'unset') . "'");
    34	    return 0 + $value;
    35	}
    36	
    37	sub ensure_percent {
    38	    my ($label, $value) = @_;
    39	    my $int = ensure_uint($label, $value);
    40	    ($int >= 0 && $int <= 100) or fatal("$label must be between 0 and 100, got $value");
    41	    return $int;
    42	}
    43	
    44	sub ensure_bool {
    45	    my ($label, $value) = @_;
    46	    defined $value or fatal("$label must be a boolean, got unset");
    47	    return 1 if $value eq '1';
    48	    return 0 if $value eq '0';
    49	    fatal("$label must be an integer 0/1 value, got '$value'");
    50	}
    51	
    52	sub decimal_to_millionths {
    53	    my ($label, $value) = @_;
    54	    defined $value && $value =~ /\A([0-9]+)(?:\.([0-9]+))?\z/
    55	        or fatal("$label must be a decimal number, got '" . (defined $value ? $value : 'unset') . "'");
    56	    my $whole = 0 + $1;
    57	    my $frac = defined $2 ? $2 : '';
    58	    $frac = substr($frac . '000000', 0, 6);
    59	    return $whole * 1_000_000 + (0 + $frac);
    60	}
