   123	    $max_bytes = ensure_positive_uint("$label maximum bytes", $max_bytes);
   124	    length($value) <= $max_bytes or fatal("$label is too large");
   125	    $value !~ /[\x00-\x1f\x7f]/ or fatal("$label contains control characters");
   126	
   127	    my @tokens = split /\s+/, $value;
   128	    @tokens or fatal("$label must contain at least one writeback token");
   129	    for my $token (@tokens) {
   130	        if (!$page_index_only && $token =~ /\Atype=(idle|huge|huge_idle|incompressible)\z/) {
   131	            next;
   132	        }
   133	        if ($token =~ /\Apage_index=([0-9]+)\z/) {
   134	            ensure_uint("$label page_index", $1);
   135	            next;
   136	        }
   137	        if ($token =~ /\Apage_indexes=([0-9]+)-([0-9]+)\z/) {
   138	            my $low = ensure_uint("$label page_indexes low", $1);
   139	            my $high = ensure_uint("$label page_indexes high", $2);
   140	            $low <= $high or fatal("$label page_indexes range must be ascending: $token");
   141	            next;
   142	        }
   143	        fatal("$label contains unsupported writeback token: $token");
   144	    }
   145	}
