    19	my $ACTIVE_LOG_LEVEL = canonical_log_level($ENV{ZRAM_LOG_LEVEL} // 'error');
    20	sub canonical_log_level {
    21	    my ($level) = @_;
    22	    $level = lc($level // 'error');
    23	    return 'warning' if $level eq 'warn';
    24	    return 'error' if $level eq 'fatal';
    25	    return exists $LOG_LEVEL_VALUE{$level} ? $level : 'error';
    26	}
    27	
    28	sub set_active_log_level {
    29	    my ($level) = @_;
    30	    $level = canonical_log_level($level);
    31	    exists $LOG_LEVEL_VALUE{$level} or $level = 'error';
    32	    $ACTIVE_LOG_LEVEL = $level;
    33	}
    34	
    35	sub log_enabled {
    36	    my ($level) = @_;
    37	    my $requested = canonical_log_level($level);
    38	    return 1 if $requested eq 'error';
    39	    return 0 if $ACTIVE_LOG_LEVEL eq 'none';
    40	    return $LOG_LEVEL_VALUE{$requested} >= $LOG_LEVEL_VALUE{$ACTIVE_LOG_LEVEL};
    41	}
