    43	sub _normalize_message {
    44	    my ($message) = @_;
    45	    $message = '' if !defined $message;
    46	    $message = "$message";
    47	    $message =~ s/[\r\n]+/ /g;
    48	    $message =~ s/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/?/g;
    49	    return $message;
    50	}
    51	
    52	sub log_msg {
    53	    my ($level, $message) = @_;
    54	    $level = canonical_log_level($level);
    55	    return if !log_enabled($level);
    56	    my %priority = (
    57	        debug   => LOG_DEBUG,
    58	        info    => LOG_INFO,
    59	        warning => LOG_WARNING,
    60	        error   => LOG_ERR,
    61	    );
    62	    my $line = _normalize_message($message);
