package TimeshiftManaged::CLI;

use strict;
use warnings;

use Moo;
use MooX::Options
  protect_argv => 0,
  flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Bool Str);

use TimeshiftManaged::GrubRefresh;
use TimeshiftManaged::Logger;
use TimeshiftManaged::Snapshot;

option help => (
    is      => 'ro',
    isa     => Bool,
    default => sub { 0 },
    doc     => 'print usage',
);

has program => (
    is       => 'ro',
    isa      => Str,
    required => 1,
);

sub _usage {
    my ($self) = @_;

    if ($self->program() eq 'timeshift-managed-snapshot') {
        print STDERR "usage: timeshift-managed-snapshot {daily|weekly|monthly}\n";
    }
    else {
        print STDERR "usage: grub-btrfs-refresh [--wait]\n";
    }
    return;
}

sub run {
    my ($self, @argv) = @_;

    local @ARGV = @argv;
    my $options = eval { __PACKAGE__->new_with_options(program => $self->program()) };
    if (!$options) {
        my $error = $@ || 'invalid command line';
        $error =~ s/\s+\z//;
        print STDERR "fatal: $error\n";
        return 1;
    }
    if ($options->help()) {
        $options->_usage();
        return 0;
    }

    if ($options->program() eq 'timeshift-managed-snapshot') {
        @ARGV == 1 or do {
            $options->_usage();
            return 1;
        };
        my $snapshot = eval { TimeshiftManaged::Snapshot->from_environment($ARGV[0]) };
        if (!$snapshot) {
            my $error = $@ || 'invalid Timeshift snapshot configuration';
            $error =~ s/\s+\z//;
            TimeshiftManaged::Logger->new(tag => 'timeshift-managed-snapshot')->error($error);
            return 1;
        }
        return $snapshot->run();
    }

    return TimeshiftManaged::GrubRefresh->new()->run(@ARGV);
}

