    if (!$options) {
        my $error = $@ || 'invalid command line';
        $error =~ s/\s+\z//;
        print STDERR "fatal: $error\n";
        return 1;
    }
    if ($options->help()) {
        _usage();
        return 0;
    }
    if (@ARGV != 1 || $ARGV[0] ne 'validate') {
        _usage();
        return 1;
    }

    my $logger = ManagedNetwork::Logger->new(
        active_level => $ENV{SYSTEMD_LOG_LEVEL} // 'error',
    );
    my $status = eval {
        ManagedNetwork::Validator->from_environment(logger => $logger)->validate();
    };
    if (!$status && $@) {
        my $error = $@;
        $error =~ s/\s+\z//;
        $logger->error($error);
        return 1;
    }
    return $status;
}

