package WhisperMode::CLI;

use strict;
use warnings;

use Moo;
use MooX::Options protect_argv => 0, flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Bool);
use WhisperMode::Runtime;

option help => (
    is      => 'ro',
    isa     => Bool,
    default => sub { 0 },
    doc     => 'print usage',
);

sub run {
    my ($class, @argv) = @_;
    local @ARGV = @argv;
    my $options = $class->new_with_options();
    if ($options->help()) {
        print STDERR "usage: whisper-record-toggle [start|stop|toggle|record-worker|transcribe|server-enabled|server]\n";
        return 0;
    }
    @ARGV <= 1 or die "whisper-record-toggle: usage: whisper-record-toggle [start|stop|toggle|record-worker|transcribe|server-enabled|server]\n";
    my $action = $ARGV[0] // 'toggle';
    $action =~ /\A(?:start|stop|toggle|record-worker|transcribe|server-enabled|server)\z/
        or die "whisper-record-toggle: invalid action\n";
    return WhisperMode::Runtime->new()->run($action);
}

